/*
 * WHO IS CALLING, AS A LEARNER (TASK-L170 §0.4). The ONE owner of this question
 * for both learner functions — two spellings of "who is this" is L102's finding.
 *
 * The Request node says only `userId` (a `_User` objectId), and a learner
 * profile holds that objectId (tools/lib/seed-resolve.mjs), so it is ONE query.
 * The first version went `_User.username` → `LearnerProfile.username`: it found
 * Sam offline and nobody live, because the backend never holds a profile's
 * username. IDENTITY COMES FROM THE SESSION AND NOTHING ELSE — there is no input
 * here a caller can set.
 *
 * A signed-in account with no learner profile (a coach reading their own
 * `course`) answers '' — a first-class state, never an error and never somebody
 * else's learner.
 */
if (Inputs.userId !== undefined) {
  (async () => {
    try {
      const userId = String(Inputs.userId || '');
      const profiles = userId
        ? await Noodl.Records.query('LearnerProfile', { userId: { equalTo: userId } }, { limit: 2, plain: true })
        : [];
      // Two profiles for one account would be two learners behind one sign-in;
      // refusing is the only answer that cannot serve the wrong one.
      if (profiles.length > 1) throw new Error('more than one learner profile for one account');
      Outputs.learnerId = profiles.length ? profiles[0].learnerId : '';
      Outputs.done();
    } catch (e) {
      Outputs.error = String((e && e.message) || e);
      // Logged for the operator; the caller still gets one refusal body (the mcp/auth.ts rule).
      console.error('[dbt:Caller learner]', Outputs.error);
      Outputs.failed();
    }
  })();
}
